(()=>{let done=false;function run(){const ws=document.querySelector('#workspace'),meta=document.querySelector('#latestMeta'),next=document.querySelector('.user-next small');if(!ws||ws.hidden||!meta||done)return;const m=meta.textContent.match(/(\d{8})/);if(!m)return;done=true;const d=new Date(`${m[1].slice(0,4)}-${m[1].slice(4,6)}-${m[1].slice(6,8)}T12:00:00`);d.setDate(d.getDate()+1);const nextDate=`${d.getFullYear()}.${String(d.getMonth()+1).padStart(2,'0')}.${String(d.getDate()).padStart(2,'0')}`;if(next)next.textContent=`최근 관측 ${m[1]} · 다음 확인 권장 ${nextDate}`;try{if(typeof target!=='undefined'&&target)localStorage.setItem('mulsallim-recent',JSON.stringify({...target,observedAt:m[1],nextCheck:nextDate,viewedAt:new Date().toISOString()}))}catch{}}new MutationObserver(run).observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['hidden']});run()})();
